import random, subprocess, os, sys, tempfile

seeds = [
 b'rule test { strings: $a="abc" $b=/x{2,3}/ $c={01??02} condition: $a at 5 and $b matches /x/ and all of them }',
 b'rule a{meta:x=1 y="s" strings:$a={0x01-0x09}[1..3] condition:uint8(0)>1 or for all i in (1..10): (@a at i)}',
 b'import "pe"\nrule b{condition: pe.entry_point(pe.sections[0].virtual_address) > 0}',
 b'rule c{condition: (5*2+1)%3 == 1 and not (filesize > 10KB) }',
 b'rule d{strings:$a="a" nocase wide ascii fullword condition:$a at (1+2)}',
 b'global rule e{strings:$a="xyz" condition:$a}',
 b'rule f{strings:$a="q" condition:#a > 0 and #a == 1}',
 b'rule g{condition: for any i in (1..5): (uint32(i) == 0)}',
]

dictw = [b'all',b'and',b'any',b'ascii',b'at',b'condition',b'contains',b'entrypoint',b'false',b'filesize',b'fullword',b'for',b'global',b'in',b'import',b'include',b'int8',b'int16',b'int32',b'matches',b'meta',b'nocase',b'not',b'of',b'or',b'private',b'rule',b'strings',b'them',b'true',b'uint8',b'uint16',b'uint32',b'wide',b'$a',b'@a',b'#a',b'..',b'..*',b'..',b'(',b')',b'{',b'}',b'[',b']',b'*',b'+',b'-',b'/',b'\\',b'"',b'\\x',b'KB',b'MB',b'0x',b'0o']

def mutate(s):
    b = bytearray(s)
    for _ in range(random.randint(1,8)):
        op = random.choice([0,1,2,3,4])
        if not b: return bytes(b)
        i = random.randrange(len(b))
        if op == 0: del b[i:i+random.randint(1,4)]
        elif op == 1: b[i:i+random.randint(1,4)] = random.choice(dictw)
        elif op == 2: b[i] = random.randrange(256)
        elif op == 3: b.insert(i, random.choice(dictw)[0])
        else: b[i:i+4] = random.choice(dictw)
    return bytes(b)

random.seed(int(sys.argv[1]) if len(sys.argv)>1 else 0)
n = int(sys.argv[2]) if len(sys.argv)>2 else 2000
os.makedirs('/tmp/crashes', exist_ok=True)
fd, path = tempfile.mkstemp(dir='/tmp')
for it in range(n):
    s = mutate(random.choice(seeds))
    with open(path,'wb') as f: f.write(s)
    try:
        p = subprocess.run(['/tmp/drv/drv', path], capture_output=True, timeout=5)
        out = p.stdout + p.stderr
        rc = p.returncode
    except subprocess.TimeoutExpired:
        print('TIMEOUT', s[:120]); continue
    if b'LeakSanitizer' not in out and (rc != 0 or b'AddressSanitizer' in out):
        fn = '/tmp/crashes/c_%d_%d' % (it, rc)
        open(fn,'wb').write(s)
        print('HARD', rc, fn, s[:150])
print('done')
